create trigger outbox_audit after insert or update or delete on public.outbox for each row execute function public.write_audit();
drop trigger if exists data_issues_stamp on public.data_issues;
create trigger data_issues_stamp before insert or update on public.data_issues for each row execute function public.stamp_attribution();
drop trigger if exists data_issues_audit on public.data_issues;
create trigger data_issues_audit after insert or update or delete on public.data_issues for each row execute function public.write_audit();
drop trigger if exists profiles_protect on public.profiles;
create trigger profiles_protect before update on public.profiles for each row execute function public.protect_profile();
drop trigger if exists form_responses_category on public.form_responses;
create trigger form_responses_category before insert or update of form_id, form_category on public.form_responses for each row execute function public.form_response_category();
drop trigger if exists forms_category_cascade on public.forms;
create trigger forms_category_cascade after update of category on public.forms for each row execute function public.form_category_cascade();
